import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.WFmvnizL.js";const b=JSON.parse('{"title":"配置加载与环境变量","description":"哪吒 Dashboard 与 Agent 配置路径、环境变量命名、加载顺序、后台保存和远程配置生效方式，解释为什么改配置后没有变化。","frontmatter":{"description":"哪吒 Dashboard 与 Agent 配置路径、环境变量命名、加载顺序、后台保存和远程配置生效方式，解释为什么改配置后没有变化。","outline":"deep"},"headers":[],"relativePath":"configuration/environment.md","filePath":"configuration/environment.md","lastUpdated":1792850916000}'),r={name:"configuration/environment.md"};function c(n,t,i,l,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="配置加载与环境变量" tabindex="-1">配置加载与环境变量 <a class="header-anchor" href="#配置加载与环境变量" aria-label="Permalink to &quot;配置加载与环境变量&quot;">​</a></h1><h2 id="找到实际使用的文件" tabindex="-1">找到实际使用的文件 <a class="header-anchor" href="#找到实际使用的文件" aria-label="Permalink to &quot;找到实际使用的文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>程序</th><th>默认位置</th><th>显式指定</th></tr></thead><tbody><tr><td>Dashboard</td><td>相对进程工作目录的 <code>data/config.yaml</code></td><td><code>./dashboard -c /path/config.yaml</code></td></tr><tr><td>Dashboard 数据库</td><td>相对工作目录的 <code>data/sqlite.db</code></td><td><code>./dashboard -db /path/sqlite.db</code></td></tr><tr><td>Agent</td><td>可执行文件所在目录的 <code>config.yml</code></td><td><code>./nezha-agent -c /path/config.yml</code></td></tr></tbody></table><p>不要仅根据文件名判断哪一份正在生效。systemd 检查 <code>ExecStart</code> 和 <code>WorkingDirectory</code>，Docker 检查容器启动参数及挂载目标。容器内路径不一定等于宿主机路径。</p><h2 id="dashboard-的命名规则" tabindex="-1">Dashboard 的命名规则 <a class="header-anchor" href="#dashboard-的命名规则" aria-label="Permalink to &quot;Dashboard 的命名规则&quot;">​</a></h2><p>Dashboard 读取前缀为 <code>NZ_</code> 的变量，去前缀后转换为小写，<strong>下划线表示嵌套层级</strong>。单个字段通常使用不带下划线的 Go 字段名。</p><table tabindex="0"><thead><tr><th>YAML 字段</th><th>环境变量</th></tr></thead><tbody><tr><td><code>listen_host</code></td><td><code>NZ_LISTENHOST</code></td></tr><tr><td><code>listen_port</code></td><td><code>NZ_LISTENPORT</code></td></tr><tr><td><code>site_name</code></td><td><code>NZ_SITENAME</code></td></tr><tr><td><code>debug</code></td><td><code>NZ_DEBUG</code></td></tr><tr><td><code>jwt_secret_key</code></td><td><code>NZ_JWTSECRETKEY</code></td></tr><tr><td><code>https.listen_port</code></td><td><code>NZ_HTTPS_LISTENPORT</code></td></tr><tr><td><code>tsdb.data_path</code></td><td><code>NZ_TSDB_DATAPATH</code></td></tr><tr><td><code>tsdb.retention_days</code></td><td><code>NZ_TSDB_RETENTIONDAYS</code></td></tr><tr><td><code>memory.go_mem_limit_mb</code></td><td><code>NZ_MEMORY_GOMEMLIMITMB</code></td></tr></tbody></table><p>例如 <code>NZ_LISTEN_PORT</code> 会被拆为 <code>listen.port</code>，不是 <code>listen_port</code>；<code>NZ_TSDB_DATA_PATH</code> 也不是 <code>tsdb.data_path</code> 的正确环境变量名。复杂列表、OAuth2 映射等优先使用 YAML，不要猜测环境变量格式。</p><h3 id="加载与持久化" tabindex="-1">加载与持久化 <a class="header-anchor" href="#加载与持久化" aria-label="Permalink to &quot;加载与持久化&quot;">​</a></h3><p>Dashboard 先加载环境变量，再合并 YAML；同名配置可能被文件值覆盖，嵌套与不同拼写的重复键更不应混用。<strong>不要把环境变量当作通用的 YAML 强制覆盖层。</strong></p><p><code>NZ_JWTSECRETKEY</code> 是明确的特例：非空时最终优先于文件中的 JWT 密钥，不写回该密钥，并跳过程序自动轮转。其它设置在后台保存时可能写回 YAML；环境变量不是通用的“不落盘”机制。</p><p>文件中的修改在重启 Dashboard 后加载。后台设置通过 API 更新运行态并保存文件；监听地址、存储和 JWT 等只读文件项不属于该设置接口。</p><h2 id="agent-的命名规则" tabindex="-1">Agent 的命名规则 <a class="header-anchor" href="#agent-的命名规则" aria-label="Permalink to &quot;Agent 的命名规则&quot;">​</a></h2><p>Agent 同样读取 <code>NZ_</code> 前缀，但<strong>保留字段中的下划线</strong>，先读 YAML，再读环境变量。简单标量的环境变量覆盖文件值。</p><table tabindex="0"><thead><tr><th>YAML 字段</th><th>环境变量</th></tr></thead><tbody><tr><td><code>server</code></td><td><code>NZ_SERVER</code></td></tr><tr><td><code>client_secret</code></td><td><code>NZ_CLIENT_SECRET</code></td></tr><tr><td><code>uuid</code></td><td><code>NZ_UUID</code></td></tr><tr><td><code>tls</code></td><td><code>NZ_TLS</code></td></tr><tr><td><code>report_delay</code></td><td><code>NZ_REPORT_DELAY</code></td></tr><tr><td><code>disable_command_execute</code></td><td><code>NZ_DISABLE_COMMAND_EXECUTE</code></td></tr></tbody></table><p>数组和映射使用 YAML 原生结构，不要把逗号分隔字符串假定为数组。环境变量由进程启动时继承；修改容器环境要重建容器，修改服务环境要重新加载服务定义并重启，单改交互式 shell 不会影响已有服务。</p><p>Agent 生成 UUID、首次创建文件或应用远程配置时会保存配置；保存后的文件包含有效配置，权限收紧为 <code>0600</code>。<strong>通过环境变量提供连接密钥不保证它永不写入 Agent 配置文件。</strong> 请保护文件和备份。</p><h2 id="远程配置不是瞬间替换" tabindex="-1">远程配置不是瞬间替换 <a class="header-anchor" href="#远程配置不是瞬间替换" aria-label="Permalink to &quot;远程配置不是瞬间替换&quot;">​</a></h2><p>后台或 <code>POST /api/v1/server/config</code> 下发 Agent 配置后，Agent 校验参数并安排约 10 秒后的应用；后到的普通配置可能替代尚未生效的普通配置。提交应答只说明已接受安排，之后仍可能因写文件失败而无法生效。</p><p>应用先保存文件，再更新运行时配置并重载工作线程。<code>debug</code>、自动更新开关和更新周期等启动时读取的选项，要完整重启 Agent 才能可靠应用。环境变量仍可能在下一次启动时覆盖远程写入的文件值。</p><ul><li><code>disable_command_execute: true</code> 也会阻止远程读取/应用配置；应在主机本地恢复。</li><li>普通配置下发不允许轮换 <code>client_secret</code>；服务器转移使用专门流程，不能用通用配置 API 代替。</li><li>下发连接地址或 TLS 参数前保留主机访问方式；连不上新入口时无法再靠旧面板远程修复。</li></ul><h2 id="排查-修改不生效" tabindex="-1">排查“修改不生效” <a class="header-anchor" href="#排查-修改不生效" aria-label="Permalink to &quot;排查“修改不生效”&quot;">​</a></h2><ol><li>确认编辑的是进程实际 <code>-c</code> 指向的文件及容器挂载。</li><li>检查是否有 <code>NZ_</code> 环境变量重复设置。检查时不要把密钥打印到日志或提交问题单。</li><li>本地文件修改后重启对应服务；修改容器环境后重新创建容器。</li><li>对远程配置等待应用窗口，查看 Agent 日志并确认重新上报；不要只看 Dashboard 提交响应。</li><li>如果设置接口保存失败，检查配置文件目录可写权限；不要只修改文件本身而忽略父目录。</li><li>对日志、API 读回和实际表现交叉验证。参见<a href="/configuration/examples.html">场景配置与验证</a>。</li></ol><h2 id="实现依据" tabindex="-1">实现依据 <a class="header-anchor" href="#实现依据" aria-label="Permalink to &quot;实现依据&quot;">​</a></h2><ul><li><a href="https://github.com/nezhahq/nezha/blob/master/model/config.go" target="_blank" rel="noreferrer">Dashboard 配置加载与保存</a></li><li><a href="https://github.com/nezhahq/nezha/blob/master/cmd/dashboard/controller/setting.go" target="_blank" rel="noreferrer">Dashboard 设置接口</a></li><li><a href="https://github.com/nezhahq/agent/blob/main/model/config.go" target="_blank" rel="noreferrer">Agent 配置加载与校验</a></li><li><a href="https://github.com/nezhahq/agent/blob/main/cmd/agent/main.go" target="_blank" rel="noreferrer">Agent 配置应用</a></li></ul>',25)])])}const g=e(r,[["render",c]]);export{b as __pageData,g as default};
